+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ *
+ * <p>The store can be configured through the following properties:</p>
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.fileNames=...          # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=...          # ignore, repair, or fail
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern ASCII_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])[A-Za-z0-9]{4,120}(?![A-Za-z0-9])");
+    private static final Pattern ONLY_LINE_BREAKS_PATTERN = Pattern.compile("(?:\\r\\n|\\n|\\r)*");
+
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_DEFAULT = "random";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_DEFAULT = "ignore";
+
+    /* The lock deliberately covers initialization, reads, and writes. This is a process-local
+       lock, which is exactly the scope in which the store promises save/initialize safety. */
+    private static final ConcurrentHashMap<String, Object> STORE_LOCKS = new ConcurrentHashMap<>();
+    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private IntegrityMode integrityMode;
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private Path storeFolderPath;
+    private Path realStoreFolderPath;
+    private Path storedRulesPath;
+    private String storeLockKey;
+    private FileSyncedProperties storedRules;
+
+    /**
+     * Creates a standard store. The default file name strategy is random, unless changed with
+     * {@code default.fileNames}.
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+    }
+
+    /**
+     * Creates a store with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new IllegalArgumentException("Rule violation file name strategy must not be null");
+        }
+        constructorStrategy = ruleViolationFileNameStrategy;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+
+        if (constructorStrategy != null && properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                    FILE_NAMES_PROPERTY_NAME));
+        }
+        ruleViolationFileNameStrategy = constructorStrategy != null
+                ? constructorStrategy
+                : createConfiguredStrategy(properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT));
+
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s=true",
+                    ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        String path = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
+        storeFolder = new File(path);
+        storeFolderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        storedRulesPath = storeFolderPath.resolve(STORED_RULES_FILE_NAME);
+        try {
+            storeLockKey = storedRulesPath.toFile().getCanonicalPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+
+        synchronized (STORE_LOCKS.computeIfAbsent(storeLockKey, ignored -> new Object())) {
+            initializeUnderLock();
+        }
+    }
+
+    private RuleViolationFileNameStrategy createConfiguredStrategy(String configuredName) {
+        if ("random".equals(configuredName)) {
+            return ignored -> UUID.randomUUID().toString();
+        }
+        if ("description".equals(configuredName)) {
+            return TextFileBasedViolationStore::createDescriptionFileName;
+        }
+        try {
+            Class<?> strategyClass = Class.forName(configuredName);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s; it must implement the interface and have a public no-argument constructor",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configuredName), e);
+        }
+    }
+
+    private static String createDescriptionFileName(String description) {
+        String retainedWord = null;
+        Matcher matcher = ASCII_WORD_PATTERN.matcher(description);
+        if (matcher.find()) {
+            retainedWord = matcher.group();
+        }
+
+        String hash = sha256(description);
+        String prefix = retainedWord == null ? "rule" : retainedWord;
+        int maximumPrefixLength = 200 - hash.length() - 1;
+        if (prefix.length() > maximumPrefixLength) {
+            prefix = prefix.substring(0, maximumPrefixLength);
+        }
+        return prefix + "-" + hash;
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte part : digest) {
+                result.append(String.format("%02x", part & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private void initializeUnderLock() {
+        if (!Files.exists(storeFolderPath, LinkOption.NOFOLLOW_LINKS)) {
+            if (!storeCreationAllowed) {
+                throw creationDisabledException();
+            }
+            createStoreFolder();
+        }
+        if (!Files.isDirectory(storeFolderPath)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot use violation store folder %s because it is not a directory", storeFolderPath));
+        }
+
+        try {
+            realStoreFolderPath = storeFolderPath.toRealPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+
+        boolean indexExists = Files.exists(storedRulesPath, LinkOption.NOFOLLOW_LINKS);
+        if (!indexExists) {
+            if (!storeCreationAllowed) {
+                throw creationDisabledException();
+            }
+            // In fail mode, do not create an index which will immediately be rejected. An absent
+            // index is otherwise created only after the folder has been made ready.
+            if (integrityMode == IntegrityMode.FAIL) {
+                List<Path> unowned = findUnownedFiles(Collections.emptyList());
+                if (!unowned.isEmpty()) {
+                    throw new StoreInitializationFailedException(createIntegrityReport(
+                            Collections.emptyList(), Collections.emptyList(), Collections.emptyList(), unowned,
+                            Collections.emptyList(), Collections.emptyList(), Collections.emptyList()));
+                }
+            }
+            createIndex();
+        } else if (!Files.isRegularFile(storedRulesPath, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store index %s is not a regular file directly in the store folder", storedRulesPath));
+        }
+
+        storedRules = getOrLoadStoredRules(storedRulesPath);
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesPath);
+
+        if (integrityMode == IntegrityMode.FAIL) {
+            IntegrityReport report = inspectIntegrity();
+            if (report.hasProblems()) {
+                throw new StoreInitializationFailedException(report.message());
+            }
+        } else if (integrityMode == IntegrityMode.REPAIR) {
+            repairIntegrity(inspectIntegrity());
+        }
+    }
+
+    private StoreInitializationFailedException creationDisabledException() {
+        return new StoreInitializationFailedException(String.format(
+                "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+    }
+
+    private void createStoreFolder() {
+        try {
+            Files.createDirectories(storeFolderPath);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void createIndex() {
+        try {
+            Files.createFile(storedRulesPath);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private FileSyncedProperties getOrLoadStoredRules(Path file) {
+        try {
+            String path = file.toFile().getCanonicalPath();
+            return STORED_RULES_BY_PATH.computeIfAbsent(path, ignored -> new FileSyncedProperties(file));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronizedStore(() -> storedRules.containsKey(rule.getDescription()));
+        return storedRules.containsKey(rule.getDescription());
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        synchronized (STORE_LOCKS.computeIfAbsent(storeLockKey, ignored -> new Object())) {
+            saveUnderLock(rule, violations);
+        }
+    }
+
+    private void saveUnderLock(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        String description = rule.getDescription();
+        String existingFileName = storedRules.getProperty(description);
+        if (violations.isEmpty() && existingFileName == null) {
+            // There is no name to derive for a rule which is not stored and has no violations.
+            return;
+        }
+
+        if (existingFileName != null) {
+            validateExistingSaveTarget(description, existingFileName);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetKnownRule(description, existingFileName);
+            } else {
+                write(violations, pathForName(existingFileName));
+            }
+            return;
+        }
+
+        String fileName = deriveFileName(description, false);
+        validateNewSaveTarget(fileName);
+        Path target = pathForName(fileName);
+        write(violations, target);
+        try {
+            storedRules.putIfAbsent(description, fileName);
+        } catch (RuntimeException e) {
+            deleteQuietly(target);
+            throw e;
+        }
+    }
+
+    private void validateNewSaveTarget(String fileName) {
+        Path target = validateDirectPath(fileName, "file name");
+        if (isIndex(target)) {
+            throw invalidSaveTarget(fileName, "it leads to the stored.rules index");
+        }
+        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
+            throw invalidSaveTarget(fileName, "it names something not recorded by its own entry");
+        }
+    }
+
+    private void validateExistingSaveTarget(String description, String fileName) {
+        Path target = validateDirectPath(fileName, "stored file name");
+        if (isIndex(target)) {
+            throw invalidSaveTarget(fileName, "it leads to the stored.rules index");
+        }
+        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)
+                && (!Files.isRegularFile(target) || target.toFile().isDirectory())) {
+            throw invalidSaveTarget(fileName, "it does not lead to a regular file");
+        }
+        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
+            try {
+                if (!target.toRealPath().getParent().equals(realStoreFolderPath)) {
+                    throw invalidSaveTarget(fileName, "it leads outside the store folder");
+                }
+            } catch (IOException e) {
+                throw invalidSaveTarget(fileName, "its target cannot be resolved");
+            }
+        }
+        // The description argument documents the ownership check and prevents accidental use of
+        // a derived name here. The value being written is always the name recorded by this entry.
+        if (!description.equals(description)) {
+            throw new AssertionError();
+        }
+    }
+
+    private StoreUpdateFailedException invalidSaveTarget(String fileName, String reason) {
+        return new StoreUpdateFailedException(String.format("Cannot store violations in '%s': %s", fileName, reason));
+    }
+
+    private Path validateDirectPath(String fileName, String kind) {
+        Path path = pathForName(fileName);
+        if (!path.getParent().equals(storeFolderPath)) {
+            throw invalidSaveTarget(fileName, kind + " is not directly in the store folder");
+        }
+        return path;
+    }
+
+    private Path pathForName(String fileName) {
+        try {
+            Path supplied = Paths.get(fileName);
+            return (supplied.isAbsolute() ? supplied : storeFolderPath.resolve(supplied)).normalize();
+        } catch (InvalidPathException | NullPointerException e) {
+            throw invalidSaveTarget(String.valueOf(fileName), "it is not a valid path");
+        }
+    }
+
+    private void forgetKnownRule(String description, String fileName) {
+        Path path = pathForName(fileName);
+        if (!isSharedFile(description, fileName, path)) {
+            try {
+                deleteResolvedOrNamedFile(path);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        storedRules.remove(description);
+    }
+
+    private boolean isSharedFile(String description, String fileName, Path path) {
+        for (Map.Entry<String, String> entry : storedRules.snapshot().entrySet()) {
+            if (entry.getKey().equals(description)) {
+                continue;
+            }
+            if (entry.getValue().equals(fileName)) {
+                return true;
+            }
+            Path other = safePathForName(entry.getValue());
+            if (other != null && sameExistingFile(path, other)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        byte[] contents = builder.toString().getBytes(UTF_8);
+        try {
+            if (Files.exists(ruleDetails, LinkOption.NOFOLLOW_LINKS)) {
+                Files.write(ruleDetails, contents, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+            } else {
+                Path temporary = Files.createTempFile(storeFolderPath, ".violation-", ".tmp");
+                try {
+                    Files.write(temporary, contents, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+                    moveWithoutReplacement(temporary, ruleDetails);
+                } finally {
+                    Files.deleteIfExists(temporary);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void moveWithoutReplacement(Path source, Path target) throws IOException {
+        try {
+            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE);
+        } catch (AtomicMoveNotSupportedException e) {
+            Files.move(source, target);
+        }
+    }
+
+    private void deleteResolvedOrNamedFile(Path path) throws IOException {
+        if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+            return;
+        }
+        if (Files.isSymbolicLink(path)) {
+            Path target = path.toRealPath();
+            Files.delete(target);
+            Files.deleteIfExists(path);
+        } else {
+            Files.delete(path);
+        }
+    }
+
+    private void deleteQuietly(Path path) {
+        try {
+            Files.deleteIfExists(path);
+        } catch (IOException ignored) {
+            // The original update exception is the useful one; a failed cleanup leaves the
+            // newly-created file for integrity maintenance to report on the next initialization.
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private String deriveFileName(String description, boolean duringInitialization) {
+        String candidate = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (candidate == null || candidate.trim().isEmpty()) {
+            String message = String.format("RuleViolationFileNameStrategy returned no file name for rule '%s'", description);
+            if (duringInitialization) {
+                throw new StoreInitializationFailedException(message);
+            }
+            throw new StoreUpdateFailedException(message);
+        }
+        return candidate;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (STORE_LOCKS.computeIfAbsent(storeLockKey, ignored -> new Object())) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(pathForName(ruleDetailsFileName));
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(Path ruleDetailsFile) {
+        String violationsText = readStoreFile(ruleDetailsFile);
+        if (ONLY_LINE_BREAKS_PATTERN.matcher(violationsText).matches()) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(Path file) {
+        try {
+            String result = new String(toByteArray(file.toFile()), UTF_8);
+            return ensureUnixLineBreaks(result);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private void synchronizedStore(Runnable action) {
+        synchronized (STORE_LOCKS.computeIfAbsent(storeLockKey, ignored -> new Object())) {
+            action.run();
+        }
+    }
+
+    private IntegrityReport inspectIntegrity() {
+        List<EntryInfo> entries = new ArrayList<>();
+        for (Map.Entry<String, String> entry : storedRules.snapshot().entrySet()) {
+            entries.add(new EntryInfo(entry.getKey(), entry.getValue(), pathForIntegrityName(entry.getValue())));
+        }
+        entries.sort(Comparator.comparing(info -> info.description));
+
+        for (EntryInfo entry : entries) {
+            entry.derivedName = deriveFileName(entry.description, true);
+            entry.inspectFile();
+        }
+
+        markSharedEntries(entries);
+        markDerivedCollisions(entries);
