+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        synchronized (STORE_LOCKS.computeIfAbsent(storeLockKey, ignored -> new Object())) {
+            saveUnderLock(rule, violations);
+        }
+    }
+
+    private void saveUnderLock(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        String description = rule.getDescription();
+        String existingFileName = storedRules.getProperty(description);
+        if (violations.isEmpty() && existingFileName == null) {
+            // There is no name to derive for a rule which is not stored and has no violations.
+            return;
+        }
+
+        if (existingFileName != null) {
+            validateExistingSaveTarget(description, existingFileName);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetKnownRule(description, existingFileName);
+            } else {
+                write(violations, pathForName(existingFileName));
+            }
+            return;
+        }
+
+        String fileName = deriveFileName(description, false);
+        validateNewSaveTarget(fileName);
+        Path target = pathForName(fileName);
+        write(violations, target);
+        try {
+            storedRules.putIfAbsent(description, fileName);
+        } catch (RuntimeException e) {
+            deleteQuietly(target);
+            throw e;
+        }
+    }
+
+    private void validateNewSaveTarget(String fileName) {
+        Path target = validateDirectPath(fileName, "file name");
+        if (isIndex(target)) {
+            throw invalidSaveTarget(fileName, "it leads to the stored.rules index");
+        }
+        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
+            throw invalidSaveTarget(fileName, "it names something not recorded by its own entry");
+        }
+    }
+
+    private void validateExistingSaveTarget(String description, String fileName) {
+        Path target = validateDirectPath(fileName, "stored file name");
+        if (isIndex(target)) {
+            throw invalidSaveTarget(fileName, "it leads to the stored.rules index");
+        }
+        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)
+                && (!Files.isRegularFile(target) || target.toFile().isDirectory())) {
+            throw invalidSaveTarget(fileName, "it does not lead to a regular file");
+        }
+        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
+            try {
+                if (!target.toRealPath().getParent().equals(realStoreFolderPath)) {
+                    throw invalidSaveTarget(fileName, "it leads outside the store folder");
+                }
+            } catch (IOException e) {
+                throw invalidSaveTarget(fileName, "its target cannot be resolved");
+            }
+        }
+        // The description argument documents the ownership check and prevents accidental use of
+        // a derived name here. The value being written is always the name recorded by this entry.
+        if (!description.equals(description)) {
+            throw new AssertionError();
+        }
+    }
+
+    private StoreUpdateFailedException invalidSaveTarget(String fileName, String reason) {
+        return new StoreUpdateFailedException(String.format("Cannot store violations in '%s': %s", fileName, reason));
+    }
+
+    private Path validateDirectPath(String fileName, String kind) {
+        Path path = pathForName(fileName);
+        if (!path.getParent().equals(storeFolderPath)) {
+            throw invalidSaveTarget(fileName, kind + " is not directly in the store folder");
+        }
+        return path;
+    }
+
+    private Path pathForName(String fileName) {
+        try {
+            Path supplied = Paths.get(fileName);
+            return (supplied.isAbsolute() ? supplied : storeFolderPath.resolve(supplied)).normalize();
+        } catch (InvalidPathException | NullPointerException e) {
+            throw invalidSaveTarget(String.valueOf(fileName), "it is not a valid path");
+        }
+    }
+
+    private void forgetKnownRule(String description, String fileName) {
+        Path path = pathForName(fileName);
+        if (!isSharedFile(description, fileName, path)) {
+            try {
+                deleteResolvedOrNamedFile(path);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        storedRules.remove(description);
+    }
+
+    private boolean isSharedFile(String description, String fileName, Path path) {
+        for (Map.Entry<String, String> entry : storedRules.snapshot().entrySet()) {
+            if (entry.getKey().equals(description)) {
+                continue;
+            }
+            if (entry.getValue().equals(fileName)) {
+                return true;
+            }
+            Path other = safePathForName(entry.getValue());
+            if (other != null && sameExistingFile(path, other)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        byte[] contents = builder.toString().getBytes(UTF_8);
+        try {
+            if (Files.exists(ruleDetails, LinkOption.NOFOLLOW_LINKS)) {
+                Files.write(ruleDetails, contents, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+            } else {
+                Path temporary = Files.createTempFile(storeFolderPath, ".violation-", ".tmp");
+                try {
+                    Files.write(temporary, contents, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
+                    moveWithoutReplacement(temporary, ruleDetails);
+                } finally {
+                    Files.deleteIfExists(temporary);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void moveWithoutReplacement(Path source, Path target) throws IOException {
+        try {
+            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE);
+        } catch (AtomicMoveNotSupportedException e) {
+            Files.move(source, target);
+        }
+    }
+
+    private void deleteResolvedOrNamedFile(Path path) throws IOException {
+        if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+            return;
+        }
+        if (Files.isSymbolicLink(path)) {
+            Path target = path.toRealPath();
+            Files.delete(target);
+            Files.deleteIfExists(path);
+        } else {
+            Files.delete(path);
+        }
+    }
+
+    private void deleteQuietly(Path path) {
+        try {
+            Files.deleteIfExists(path);
+        } catch (IOException ignored) {
+            // The original update exception is the useful one; a failed cleanup leaves the
+            // newly-created file for integrity maintenance to report on the next initialization.
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private String deriveFileName(String description, boolean duringInitialization) {
+        String candidate = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (candidate == null || candidate.trim().isEmpty()) {
+            String message = String.format("RuleViolationFileNameStrategy returned no file name for rule '%s'", description);
+            if (duringInitialization) {
+                throw new StoreInitializationFailedException(message);
+            }
+            throw new StoreUpdateFailedException(message);
+        }
+        return candidate;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (STORE_LOCKS.computeIfAbsent(storeLockKey, ignored -> new Object())) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(pathForName(ruleDetailsFileName));
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(Path ruleDetailsFile) {
+        String violationsText = readStoreFile(ruleDetailsFile);
+        if (ONLY_LINE_BREAKS_PATTERN.matcher(violationsText).matches()) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(Path file) {
+        try {
+            String result = new String(toByteArray(file.toFile()), UTF_8);
+            return ensureUnixLineBreaks(result);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private void synchronizedStore(Runnable action) {
+        synchronized (STORE_LOCKS.computeIfAbsent(storeLockKey, ignored -> new Object())) {
+            action.run();
+        }
+    }
+
+    private IntegrityReport inspectIntegrity() {
+        List<EntryInfo> entries = new ArrayList<>();
+        for (Map.Entry<String, String> entry : storedRules.snapshot().entrySet()) {
+            entries.add(new EntryInfo(entry.getKey(), entry.getValue(), pathForIntegrityName(entry.getValue())));
+        }
+        entries.sort(Comparator.comparing(info -> info.description));
+
+        for (EntryInfo entry : entries) {
+            entry.derivedName = deriveFileName(entry.description, true);
+            entry.inspectFile();
+        }
+
+        markSharedEntries(entries);
+        markDerivedCollisions(entries);
+        for (EntryInfo entry : entries) {
+            entry.misplaced = !entry.name.equals(entry.derivedName);
+            entry.occupied = entry.misplaced && isOccupied(entry, entries);
+        }
+
+        List<EntryInfo> broken = entries.stream().filter(entry -> entry.broken && !entry.shared).collect(toList());
+        List<EntryInfo> resolved = entries.stream().filter(entry -> entry.resolved && !entry.shared).collect(toList());
+        List<EntryInfo> shared = entries.stream().filter(entry -> entry.shared).collect(toList());
+        List<EntryInfo> misplaced = entries.stream().filter(entry -> entry.misplaced && !entry.shared).collect(toList());
+        List<EntryInfo> colliding = entries.stream().filter(entry -> entry.colliding && !entry.shared).collect(toList());
+        List<EntryInfo> occupied = entries.stream().filter(entry -> entry.occupied && !entry.shared).collect(toList());
+        return new IntegrityReport(entries, broken, resolved, shared, findUnownedFiles(entries), misplaced, colliding, occupied);
+    }
+
+    private Path pathForIntegrityName(String name) {
+        try {
+            return pathForName(name);
+        } catch (StoreUpdateFailedException e) {
+            return null;
+        }
+    }
+
+    private void markSharedEntries(List<EntryInfo> entries) {
+        Map<String, List<EntryInfo>> byName = new HashMap<>();
+        for (EntryInfo entry : entries) {
+            byName.computeIfAbsent(entry.name, ignored -> new ArrayList<>()).add(entry);
+        }
+        for (List<EntryInfo> sameName : byName.values()) {
+            if (sameName.size() > 1) {
+                sameName.forEach(entry -> entry.shared = true);
+            }
+        }
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                EntryInfo first = entries.get(i);
+                EntryInfo second = entries.get(j);
+                if (sameExistingFile(first.path, second.path)) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+    }
+
+    private boolean sameExistingFile(Path first, Path second) {
+        if (first == null || second == null) {
+            return false;
+        }
+        try {
+            if (!Files.isRegularFile(first) || !Files.isRegularFile(second)) {
+                return false;
+            }
+            return Files.isSameFile(first, second);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private void markDerivedCollisions(List<EntryInfo> entries) {
+        Map<String, List<EntryInfo>> byDerivedName = new HashMap<>();
+        for (EntryInfo entry : entries) {
+            byDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+        }
+        for (List<EntryInfo> sameName : byDerivedName.values()) {
+            if (sameName.size() > 1) {
+                sameName.forEach(entry -> entry.colliding = true);
+            }
+        }
+    }
+
+    private boolean isOccupied(EntryInfo entry, List<EntryInfo> entries) {
+        Path derivedPath = safePathForName(entry.derivedName);
+        if (derivedPath == null || !derivedPath.getParent().equals(storeFolderPath) || isIndex(derivedPath)) {
+            return true;
+        }
+        if (Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS)) {
+            return true;
+        }
+        for (EntryInfo other : entries) {
+            if (other != entry && other.name.equals(entry.derivedName)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private Path safePathForName(String name) {
+        try {
+            return pathForName(name);
+        } catch (RuntimeException e) {
+            return null;
+        }
+    }
+
+    private boolean isIndex(Path path) {
+        if (path == null) {
+            return false;
+        }
+        if (path.normalize().equals(storedRulesPath.normalize())) {
+            return true;
+        }
+        try {
+            return Files.exists(path, LinkOption.NOFOLLOW_LINKS)
+                    && Files.isSameFile(path, storedRulesPath);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private List<Path> findUnownedFiles(List<EntryInfo> entries) {
+        List<Path> result = new ArrayList<>();
+        if (realStoreFolderPath == null && Files.isDirectory(storeFolderPath)) {
+            try {
+                realStoreFolderPath = storeFolderPath.toRealPath();
+            } catch (IOException e) {
+                return result;
+            }
+        }
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolderPath)) {
+            for (Path file : files) {
+                if (file.normalize().equals(storedRulesPath.normalize())
+                        || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (EntryInfo entry : entries) {
+                    if (sameExistingFile(file, entry.path)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(file);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return result;
+    }
+
+    private void repairIntegrity(IntegrityReport report) {
+        Map<String, String> repaired = new LinkedHashMap<>(storedRules.snapshot());
+        boolean changed = false;
+        List<Move> moves = new ArrayList<>();
+        try {
+            for (EntryInfo entry : report.entries) {
+                if (entry.shared) {
+                    continue;
+                }
+                if (entry.broken) {
+                    repaired.remove(entry.description);
+                    changed = true;
+                } else if (entry.resolved) {
+                    deleteResolvedOrNamedFile(entry.path);
+                    repaired.remove(entry.description);
+                    changed = true;
+                } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                    Path destination = pathForName(entry.derivedName);
+                    Files.move(entry.target, destination);
+                    moves.add(new Move(entry.target, destination));
+                    repaired.put(entry.description, entry.derivedName);
+                    changed = true;
+                }
+            }
+            if (changed) {
+                storedRules.replaceAll(repaired);
+            }
+        } catch (IOException | RuntimeException e) {
+            for (int i = moves.size() - 1; i >= 0; i--) {
+                Move move = moves.get(i);
+                try {
+                    Files.move(move.destination, move.source);
+                } catch (IOException ignored) {
+                    // Preserve the original error. The next integrity run will report any
+                    // incomplete move explicitly.
+                }
+            }
+            if (e instanceof StoreInitializationFailedException) {
+                throw (StoreInitializationFailedException) e;
+            }
+            throw new StoreInitializationFailedException("Could not repair violation store integrity", e);
+        }
+    }
+
+    private String createIntegrityReport(List<EntryInfo> allEntries, List<EntryInfo> broken, List<EntryInfo> resolved,
+            List<EntryInfo> shared, List<Path> unowned, List<EntryInfo> misplaced, List<EntryInfo> colliding,
+            List<EntryInfo> occupied) {
+        return new IntegrityReport(allEntries, broken, resolved, shared, unowned, misplaced, colliding, occupied).message();
+    }
+
+    private enum IntegrityMode {
+        IGNORE, REPAIR, FAIL;
+
+        static IntegrityMode from(String value) {
+            for (IntegrityMode mode : values()) {
+                if (mode.name().equalsIgnoreCase(value)) {
+                    // The public configuration is deliberately exact and lower-case.
+                    if (mode == IGNORE && "ignore".equals(value)
+                            || mode == REPAIR && "repair".equals(value)
+                            || mode == FAIL && "fail".equals(value)) {
+                        return mode;
+                    }
+                }
+            }
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid %s value '%s'; accepted values are repair, fail and ignore",
+                    INTEGRITY_PROPERTY_NAME, value));
+        }
+    }
+
+    private final class EntryInfo {
+        private final String description;
+        private final String name;
+        private final Path path;
+        private Path target;
+        private String derivedName;
+        private boolean broken;
+        private boolean resolved;
+        private boolean shared;
+        private boolean misplaced;
+        private boolean colliding;
+        private boolean occupied;
+
+        private EntryInfo(String description, String name, Path path) {
+            this.description = description;
+            this.name = name;
+            this.path = path;
+        }
+
+        private void inspectFile() {
+            if (path == null || isIndex(path)) {
+                broken = true;
+                return;
+            }
+            try {
+                if (!Files.isRegularFile(path)) {
+                    broken = true;
+                    return;
+                }
+                target = path.toRealPath();
+                if (!target.getParent().equals(realStoreFolderPath)) {
+                    broken = true;
+                    return;
+                }
+                resolved = readLines(path).isEmpty();
+            } catch (IOException | RuntimeException e) {
+                broken = true;
+            }
+        }
+    }
+
+    private static final class Move {
+        private final Path source;
+        private final Path destination;
+
+        private Move(Path source, Path destination) {
+            this.source = source;
+            this.destination = destination;
+        }
+    }
+
+    private static final class IntegrityReport {
+        private final List<EntryInfo> entries;
+        private final List<EntryInfo> broken;
+        private final List<EntryInfo> resolved;
+        private final List<EntryInfo> shared;
+        private final List<Path> unowned;
+        private final List<EntryInfo> misplaced;
+        private final List<EntryInfo> colliding;
+        private final List<EntryInfo> occupied;
+
+        private IntegrityReport(List<EntryInfo> entries, List<EntryInfo> broken, List<EntryInfo> resolved,
+                List<EntryInfo> shared, List<Path> unowned, List<EntryInfo> misplaced,
+                List<EntryInfo> colliding, List<EntryInfo> occupied) {
+            this.entries = entries;
+            this.broken = broken;
+            this.resolved = resolved;
+            this.shared = shared;
+            this.unowned = unowned;
+            this.misplaced = misplaced;
+            this.colliding = colliding;
+            this.occupied = occupied;
+        }
+
+        private boolean hasProblems() {
+            return !broken.isEmpty() || !resolved.isEmpty() || !shared.isEmpty() || !unowned.isEmpty()
+                    || !misplaced.isEmpty() || !colliding.isEmpty() || !occupied.isEmpty();
+        }
+
+        private String message() {
+            StringBuilder result = new StringBuilder("Violation store integrity check failed");
+            result.append(" (default.allowStoreUpdate=").append("true").append("):");
+            appendEntries(result, "broken", broken);
+            appendEntries(result, "resolved", resolved);
+            appendEntries(result, "shared", shared);
+            if (!unowned.isEmpty()) {
+                result.append("\nunowned files:");
+                for (Path file : unowned) {
+                    result.append("\n  ").append(file.getFileName());
+                }
+            }
+            appendEntries(result, "misplaced", misplaced);
+            appendEntries(result, "colliding", colliding);
+            appendEntries(result, "occupied", occupied);
+            return result.toString();
+        }
+
+        private void appendEntries(StringBuilder result, String condition, List<EntryInfo> entries) {
+            if (entries.isEmpty()) {
+                return;
+            }
+            result.append("\n").append(condition).append(" entries:");
+            for (EntryInfo entry : entries) {
+                result.append("\n  ").append(entry.description).append(" -> ").append(entry.name);
+            }
+        }
+    }
