+    private static class FileSyncedProperties {
+        private final Path propertiesFile;
+        private final Properties loadedProperties;
+
+        FileSyncedProperties(Path file) {
+            propertiesFile = file;
+            loadedProperties = loadRulesFrom(file);
+        }
+
+        private Properties loadRulesFrom(Path file) {
+            Properties result = new Properties();
+            try (FileInputStream inputStream = new FileInputStream(file.toFile())) {
+                result.load(inputStream);
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+            return result;
+        }
+
+        synchronized boolean containsKey(String propertyName) {
+            return loadedProperties.containsKey(ensureUnixLineBreaks(propertyName));
+        }
+
+        synchronized String getProperty(String propertyName) {
+            return loadedProperties.getProperty(ensureUnixLineBreaks(propertyName));
+        }
+
+        synchronized Map<String, String> snapshot() {
+            Map<String, String> result = new HashMap<>();
+            for (String name : loadedProperties.stringPropertyNames()) {
+                result.put(name, loadedProperties.getProperty(name));
+            }
+            return result;
+        }
+
+        synchronized void putIfAbsent(String key, String value) {
+            String normalizedKey = ensureUnixLineBreaks(key);
+            if (loadedProperties.containsKey(normalizedKey)) {
+                return;
+            }
+            loadedProperties.setProperty(normalizedKey, ensureUnixLineBreaks(value));
+            try {
+                syncFileSystem();
+            } catch (RuntimeException e) {
+                loadedProperties.remove(normalizedKey);
+                throw e;
+            }
+        }
+
+        synchronized void remove(String key) {
+            String normalizedKey = ensureUnixLineBreaks(key);
+            Object oldValue = loadedProperties.remove(normalizedKey);
+            if (oldValue == null) {
+                return;
+            }
+            try {
+                syncFileSystem();
+            } catch (RuntimeException e) {
+                loadedProperties.setProperty(normalizedKey, String.valueOf(oldValue));
+                throw e;
+            }
+        }
+
+        synchronized void replaceAll(Map<String, String> values) {
+            Properties old = new Properties();
+            old.putAll(loadedProperties);
+            loadedProperties.clear();
+            for (Map.Entry<String, String> entry : values.entrySet()) {
+                loadedProperties.setProperty(ensureUnixLineBreaks(entry.getKey()), ensureUnixLineBreaks(entry.getValue()));
+            }
+            try {
+                syncFileSystem();
+            } catch (RuntimeException e) {
+                loadedProperties.clear();
+                loadedProperties.putAll(old);
+                throw e;
+            }
+        }
+
+        private void syncFileSystem() {
+            Path temporary = null;
+            try {
+                temporary = Files.createTempFile(propertiesFile.getParent(), ".stored-rules-", ".tmp");
+                try (java.io.OutputStream output = Files.newOutputStream(temporary, StandardOpenOption.WRITE,
+                        StandardOpenOption.TRUNCATE_EXISTING)) {
+                    loadedProperties.store(output, "");
+                }
+                try {
+                    Files.move(temporary, propertiesFile, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+                } catch (AtomicMoveNotSupportedException e) {
+                    Files.move(temporary, propertiesFile, StandardCopyOption.REPLACE_EXISTING);
+                }
+                temporary = null;
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            } finally {
+                if (temporary != null) {
+                    try {
+                        Files.deleteIfExists(temporary);
+                    } catch (IOException ignored) {
+                        // Preserve the update failure.
+                    }
+                }
+            }
+        }
+    }
